import data from "./demo-data.json";

/**
 * DCA Guardian Agent — dashboard.
 *
 * Demo mode: renders the scripted local simulation produced by
 * `agent/src/simulate.ts` (src/demo-data.json). Every number on this page —
 * the buys, the two circuit-breaker holds, the daily-cap stop, the command
 * verification results — was generated by actually running the agent code,
 * not typed in by hand. On Diana the same panels read GuardianVault.getState(),
 * breakerStatus() and the agent's JSONL log directly.
 */

interface Decision {
  at: number;
  price: number;
  action: string;
  amount: number;
  reason: string;
  detail: string;
  deviationBps: number;
  txHash: string | null;
  source: string;
}

const decisions = data.decisions as Decision[];
const series = data.priceSeries as { at: number; price: number }[];

function fmtTime(unix: number): string {
  return new Date(unix * 1000).toISOString().slice(11, 16) + " UTC";
}

function shortHash(h: string | null): string {
  if (!h) return "—";
  return h.slice(0, 10) + "…" + h.slice(-6);
}

function PriceChart() {
  const w = 640;
  const h = 170;
  const pad = 28;
  const prices = series.map((p) => p.price);
  const min = Math.min(...prices) * 0.97;
  const max = Math.max(...prices) * 1.03;
  const x = (i: number) => pad + (i * (w - 2 * pad)) / (series.length - 1);
  const y = (p: number) => h - pad - ((p - min) / (max - min)) * (h - 2 * pad);
  const points = series.map((p, i) => `${x(i)},${y(p.price)}`).join(" ");
  return (
    <svg viewBox={`0 0 ${w} ${h}`} className="chart" role="img" aria-label="AMM price series">
      <polyline points={points} fill="none" stroke="var(--accent)" strokeWidth="2.5" />
      {series.map((p, i) => (
        <g key={p.at}>
          <circle cx={x(i)} cy={y(p.price)} r="4.5" fill="var(--panel)" stroke="var(--accent)" strokeWidth="2" />
          <text x={x(i)} y={y(p.price) - 10} textAnchor="middle" className="chart-label">
            {p.price.toFixed(2)}
          </text>
          <text x={x(i)} y={h - 8} textAnchor="middle" className="chart-label">
            {fmtTime(p.at)}
          </text>
        </g>
      ))}
    </svg>
  );
}

export default function App() {
  const capPct = Math.min(100, (data.vault.spentToday / data.config.dailyCap) * 100);
  return (
    <div className="wrap">
      <header className="top">
        <h1>
          DCA Guardian <span>Agent</span>
        </h1>
        <div className="badges">
          <span className="badge">QoreChain Diana · EVM 9800</span>
          <span className="badge">ML-DSA-87 kill-switch</span>
          <span className="badge demo">DEMO — local simulation data</span>
        </div>
      </header>
      <p className="sub">
        An autonomous DCA agent whose leash is a contract, not a promise. The agent's key can
        only call <code>GuardianVault.executeDca()</code> — inside a per-tx cap, a daily cap
        (UTC bucket), a minimum interval and a volatility circuit-breaker, on exactly one AMM
        and one token pair. It can never withdraw. The owner stops it permanently with an
        ML-DSA-87 signature verified on chain.
      </p>

      <div className="stats">
        <div className="card stat">
          <div className="stat-label">Agent status</div>
          <div className="stat-value ok">{data.agentStatus}</div>
          <div className="stat-note">owner key fp: {data.ownerPubkeyFingerprint}</div>
        </div>
        <div className="card stat">
          <div className="stat-label">Kill-switch</div>
          <div className="stat-value">{data.killSwitch.engaged ? "ENGAGED" : "armed · off"}</div>
          <div className="stat-note">owner + ML-DSA-87 only, one-way</div>
        </div>
        <div className="card stat">
          <div className="stat-label">Circuit-breaker</div>
          <div className="stat-value warn">{data.breaker.trippedCount} holds</div>
          <div className="stat-note">
            anchor {data.breaker.anchorPrice.toFixed(2)} · threshold{" "}
            {data.breaker.thresholdBps / 100}% / {data.breaker.windowSec / 3600}h
          </div>
        </div>
        <div className="card stat">
          <div className="stat-label">Executions</div>
          <div className="stat-value">{data.vault.executions} buys</div>
          <div className="stat-note">every one inside the caps, on record below</div>
        </div>
      </div>

      <div className="grid">
        <div className="card">
          <h2>AMM price (QOR per fUSD)</h2>
          <PriceChart />
          <h3>Vault position</h3>
          <div className="kv">
            <span>Spend balance (fUSD)</span>
            <strong>{data.vault.spendBalance.toLocaleString()}</strong>
            <span>Acquired (QOR)</span>
            <strong>{data.vault.targetBalance.toLocaleString()}</strong>
            <span>Spent today</span>
            <strong>
              {data.vault.spentToday} / {data.config.dailyCap} fUSD
            </strong>
          </div>
          <div className="capbar">
            <div className="capfill" style={{ width: `${capPct}%` }} />
          </div>
          <p className="note">
            Daily cap is a hard on-chain limit in a UTC day bucket — at 100% the vault rejects
            further buys until the next UTC day, no matter what the agent asks for.
          </p>
        </div>

        <div className="card">
          <h2>Authenticated owner commands</h2>
          <p className="note">
            Remote commands must carry the owner's ML-DSA-87 signature (nonce + expiry). The
            simulation exercised all three cases:
          </p>
          <table className="cmdtable">
            <tbody>
              {data.commandDemo.map((c) => (
                <tr key={c.label}>
                  <td>{c.label}</td>
                  <td>
                    <span className={c.result === "accepted" ? "pill ok" : "pill bad"}>
                      {c.result}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <h3>The leash, layer by layer</h3>
          <ul className="layers">
            <li>
              <strong>Layer A — scoped EVM window (chain):</strong> the agent account's window
              admits only calls to the vault, with tx/value budgets.
            </li>
            <li>
              <strong>Layer B — GuardianVault (contract):</strong> caps, interval,
              circuit-breaker, single venue/pair; withdraw &amp; kill are owner + ML-DSA only.
            </li>
            <li>
              <strong>Layer C — abstract account (native):</strong> session key with
              least-privilege <code>evm/amm</code> permissions and on-chain spending rules —
              see <code>docs/ABSTRACT_ACCOUNT_PLAN.md</code>.
            </li>
          </ul>
        </div>
      </div>

      <div className="card logcard">
        <h2>Decision log (JSONL, append-only)</h2>
        <table className="logtable">
          <thead>
            <tr>
              <th>Time</th>
              <th>Price</th>
              <th>Decision</th>
              <th>Amount</th>
              <th>Reason</th>
              <th>Deviation</th>
              <th>Tx</th>
            </tr>
          </thead>
          <tbody>
            {decisions.map((d, i) => (
              <tr key={i}>
                <td>{fmtTime(d.at)}</td>
                <td>{d.price.toFixed(2)}</td>
                <td>
                  <span className={d.action === "buy" ? "pill ok" : "pill hold"}>
                    {d.action.toUpperCase()}
                  </span>
                </td>
                <td>{d.action === "buy" ? `${d.amount} fUSD` : "—"}</td>
                <td>{d.reason}</td>
                <td>{d.deviationBps} bps</td>
                <td title={d.txHash ?? ""}>{shortHash(d.txHash)}</td>
              </tr>
            ))}
          </tbody>
        </table>
        <p className="note">{data.note}</p>
      </div>
    </div>
  );
}
